    z_t2286_t proto = {0};
    z_t2285_t* boxed = (z_t2285_t*)z_xmalloc(sizeof(z_t2285_t));
    *boxed = *val;
    proto.data = boxed;
    proto.vtable = &z_t2285_Reader_vtable;
    proto.destroy = z_t2285_Reader_owned_destroy;
